USE cuea_lost_found;
ALTER TABLE items ADD COLUMN IF NOT EXISTS brand VARCHAR(100) NULL AFTER image, ADD COLUMN IF NOT EXISTS model VARCHAR(120) NULL AFTER brand, ADD COLUMN IF NOT EXISTS color VARCHAR(80) NULL AFTER model, ADD COLUMN IF NOT EXISTS serial_number VARCHAR(150) NULL AFTER color, ADD COLUMN IF NOT EXISTS reviewed_by_staff_id INT NULL AFTER status, ADD COLUMN IF NOT EXISTS reviewed_by_admin_id INT NULL AFTER reviewed_by_staff_id;
ALTER TABLE items MODIFY status ENUM('pending','approved','claimed','issued','rejected') DEFAULT 'pending';
ALTER TABLE claims ADD COLUMN IF NOT EXISTS reviewed_by_staff_id INT NULL AFTER status, ADD COLUMN IF NOT EXISTS reviewed_by_admin_id INT NULL AFTER reviewed_by_staff_id, ADD COLUMN IF NOT EXISTS reviewed_at DATETIME NULL AFTER reviewed_by_admin_id, ADD COLUMN IF NOT EXISTS issued_at DATETIME NULL AFTER reviewed_at;
ALTER TABLE claims MODIFY status ENUM('pending','approved','rejected','issued') DEFAULT 'pending';
CREATE TABLE IF NOT EXISTS issued_items (id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,claim_id INT NOT NULL,issued_to_user_id INT NULL,issued_to_name VARCHAR(150) NOT NULL,issued_by_staff_id INT NULL,issued_by_admin_id INT NULL,issued_by_name VARCHAR(150) NOT NULL,issuer_role ENUM('staff','admin') NOT NULL,verification_notes TEXT NULL,issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_claim_issue(claim_id));
CREATE TABLE IF NOT EXISTS activity_logs (id INT AUTO_INCREMENT PRIMARY KEY,actor_type VARCHAR(30) NOT NULL,actor_id INT NULL,actor_name VARCHAR(150) NOT NULL,action VARCHAR(150) NOT NULL,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
